import {supabaseConfig} from './config.js';
import {createBackend} from './backend.js';
import {createReader,decisionNarration} from './reader.js';
import {products,compare} from './catalog.js';
const $=s=>document.querySelector(s),main=$('#main');
const backend=createBackend(supabaseConfig,()=>import('./vendor/supabase.js'));
let savedLoading=false,savedError='',sessionVersion=0,savePending=false,mutationQueue=Promise.resolve();
const mutate=task=>{const pending=mutationQueue.then(task);mutationQueue=pending.catch(()=>{});return pending;};
const state={routine:[],candidate:'sample_5',goal:'Hydration',budget:'',sensitive:false,saved:[],scan:null};
try{if(!backend.configured)state.saved=JSON.parse(localStorage.getItem('shelfcheck-saved')||'[]');if(!Array.isArray(state.saved))state.saved=[];}catch{state.saved=[];}
let page='home',query='',category='All products',result=null,file=null,photoUrl=null,scanController=null;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const current=()=>products.filter(p=>state.routine.includes(p.id));
const candidate=()=>products.find(p=>p.id===state.candidate);
const art=(p,extra='')=>`<div class="product-object ${p.shape} ${p.color} ${extra}" aria-hidden="true"><span class="bname">still.</span><span class="pname">${esc(p.name)}</span><span class="pvolume">${p.shape==='jar'?'50 ML':'30 ML'} / DAILY RITUAL</span></div>`;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3000);}
function modal(html){$('#modal-body').innerHTML=html;$('#modal').showModal();}
function counters(){$('#shelf-count').textContent=state.routine.length;$('#save-count').textContent=state.saved.length;}
function go(next,focus=true){reader.stop('Ready to read.');page=next;query='';category='All products';document.querySelectorAll('.nav').forEach(n=>{const active=n.dataset.page===next;n.classList.toggle('active',active);if(active)n.setAttribute('aria-current','page');else n.removeAttribute('aria-current');});$('#breadcrumb').textContent=({home:'Your overview',shelf:'Your personal shelf',check:'A thoughtful purchase',scan:'Your skin insights',saved:'Your saved decisions',decision:'Your product decision'})[next];render();counters();if(focus){main.focus();window.scrollTo(0,0);}}
function heading(k,title,sub){return `<div class="page-heading"><div class="eyebrow">${k}</div><h1>${title}</h1><p>${sub}</p></div>`;}
function home(){const shelf=current();return `<div class="intro"><div><div class="eyebrow">A LITTLE CLARITY FOR YOUR SKINCARE</div><h1>Good skin. Thoughtful choices.</h1><p>Get to know your shelf before you add to it.</p></div><span class="session-tag">✧ &nbsp; Your routine, your pace</span></div><section class="hero"><div class="hero-copy"><span class="pill">CONSIDER BEFORE YOU COMMIT</span><h2>Does your skin need<br>that next product?</h2><p>Check it against what you already use.<br>Keep what works. Skip what doesn’t add up.</p><div class="hero-actions"><button class="primary" data-go="check">Check a product <span>↗</span></button><button class="link-btn" id="how">How it works &nbsp; →</button></div></div><div class="hero-art"><div class="art-ring"></div>${art(products[0])}${art(products[1])}${art(products[3])}<span class="art-label">A MORE INTENTIONAL EVERYDAY</span><div class="tiny-sticker">♡ &nbsp; Your shelf is a good place to start.</div></div></section><div class="content-grid"><section class="shelf-panel"><div class="section-head"><h2>Your shelf <small>${shelf.length} products</small></h2><button data-go="shelf">View shelf &nbsp; ↗</button></div><div class="shelf-items">${(shelf.length?shelf.slice(0,3):products.slice(0,3)).map(p=>`<div class="product-mini"><div class="mini-stage">${art(p)}</div><strong>${esc(p.name)}</strong><small>${shelf.length?p.category:'SAMPLE · '+p.category}</small></div>`).join('')}<button class="add-tile" data-go="shelf"><span>+</span>Add a product</button></div><div class="shelf-foot">${shelf.length?'✓ &nbsp; Your selected routine. Edit it whenever you need.':'♧ &nbsp; A little shelf inspiration. Add the products you use.'}</div></section><section class="insight-panel"><span class="optional">OPTIONAL</span><span class="scan-icon">☼</span><h3>Your skin adds<br>another layer of context.</h3><p>An opt-in skin scan can add observations to your routine. Your photo, your choice.</p><button class="secondary" data-go="scan">Explore skin insights <span>↗</span></button></section></div><div class="bottom-grid"><section class="decision-preview"><span class="tip-icon">✦</span><div><div class="eyebrow">A SMALL REMINDER</div><h3>More products ≠ a better routine.</h3><p>Sometimes, the most thoughtful purchase is the one you pause.</p></div><button id="tip" aria-label="Read about thoughtful purchasing">↗</button></section><section class="steps-panel"><h3>A clearer decision, in three steps.</h3><div class="steps-row"><span><b>1</b> Build your shelf</span><span><b>2</b> Pick a product</span><span><b>3</b> Get clarity</span></div></section></div>`;}
function catalogGrid(mode){const list=products.filter(p=>(category==='All products'||p.category===category)&&`${p.name} ${p.ingredients.join(' ')}`.toLowerCase().includes(query.toLowerCase()));return list.length?list.map(p=>`<article class="catalog-card"><div class="mini-stage">${art(p)}</div><div class="eyebrow">${esc(p.category)} · FICTIONAL SAMPLE</div><h3>${esc(p.name)}</h3><p>${p.ingredients.length?esc(p.ingredients.join(' · ')):'Ingredient data unavailable'}</p><div class="card-bottom"><span>${p.price?'$'+p.price.toFixed(2):'Price unknown'}</span><button data-${mode}="${p.id}" class="${state.routine.includes(p.id)?'selected':''}">${mode==='add'?(state.routine.includes(p.id)?'✓ Added':'+ Add to shelf'):'Check this →'}</button></div></article>`).join(''):'<p class="muted">No products match. Try another name or ingredient.</p>';}
function tools(){return `<div class="catalog-tools"><input class="search" type="search" id="search" placeholder="Search products or ingredients" aria-label="Search products or ingredients"><select id="category" aria-label="Filter product category">${['All products','Cleanser','Moisturizer','Sunscreen','Serum','Treatment'].map(x=>`<option>${x}</option>`).join('')}</select></div>`;}
function shelf(){return heading('YOUR ROUTINE, AT A GLANCE','A home for what you already have.','Add products from the sample collection. Start with the essentials you use regularly.')+`<div class="panel"><div class="section-head"><h2>My routine <small>${state.routine.length} products selected</small></h2><button class="link-btn" data-go="check">Check a new product ↗</button></div><div class="button-row" style="margin:0">${current().length?current().map(p=>`<button class="secondary" data-add="${p.id}">${esc(p.name)} &nbsp; ×</button>`).join(''):'<p class="muted">Your shelf is empty. Add a product below, or continue with a beginner comparison.</p>'}</div></div>${tools()}<div class="catalog-grid" id="catalog">${catalogGrid('add')}</div><p class="sample-label">All 16 products are fictional demonstration items. Ingredient lists are illustrative, not complete formulations. USD prices are examples.</p>`;}
function check(){return heading('PAUSE. COMPARE. DECIDE.','What are you thinking of buying?','One product, considered in the context of your routine.')+`<div class="progress"><span>1. Your shelf (${state.routine.length})</span><span>2. Your next product</span><span>3. Your decision</span></div><div class="split"><section class="panel"><form id="compare-form"><label class="form-field">Product to check<select id="candidate">${products.map(p=>`<option value="${p.id}" ${p.id===state.candidate?'selected':''}>${esc(p.name)} — ${p.category}${p.price?' · $'+p.price:''}</option>`).join('')}</select></label><div id="candidate-info">${candidateInfo()}</div><label class="form-field">What would you like to focus on?<select id="goal">${['Hydration','Uneven tone','Texture','Blemish appearance','Sun protection','A simpler routine'].map(g=>`<option ${state.goal===g?'selected':''}>${g}</option>`).join('')}</select></label><label class="form-field">Your budget for this product (USD, optional)<input id="budget" type="number" min="0" max="10000" step="0.01" value="${esc(state.budget)}" placeholder="e.g. 25"></label><label class="check-row"><input id="sensitive" type="checkbox" ${state.sensitive?'checked':''}>I experience sensitivity or irritation.</label><button type="submit" class="primary">Check this product <span>↗</span></button></form></section><aside><section class="panel"><div class="section-head"><h2>Your shelf</h2><button data-go="shelf">Edit ↗</button></div>${current().length?current().map(p=>`<p class="muted">✓ &nbsp; ${esc(p.name)}<br><small style="margin-left:22px">${esc(p.category)}</small></p>`).join(''):'<p class="muted">No products yet. You can compare in beginner mode, or add your routine for more context.</p><button class="secondary" data-go="shelf">Build my shelf +</button>'}</section><section class="panel" style="margin-top:18px"><span class="eyebrow">YOUR CONTEXT</span><h3>${state.scan?'YouCam observations available':'No skin scan used'}</h3><p class="muted">A scan is optional. This check uses sample product data, your goal and your selected routine.</p><button class="link-btn" data-go="scan">${state.scan?'View observations':'Add skin context (optional)'} →</button></section><p class="muted" style="padding:16px;font-size:10px">Educational shopping support. We can’t diagnose skin conditions, determine allergies or predict how a product will work for you.</p></aside></div>`;}
function candidateInfo(){const p=candidate();return `<div class="selected-info"><b>${esc(p.name)}</b><p>${esc(p.ingredients.join(' · ')||'Ingredients unavailable')}</p><p>Stated purpose: ${esc(p.claim)}</p><small>Source: fictional sample catalogue · formulation unverified</small></div>`;}
const labels={hold:'Give this purchase a pause.',consider:'Worth a closer look.',skip:'You may not need another.',needs_more_info:'A little more information first.'};
function decision(){if(!result)return check();return heading('YOUR SHELFCHECK','A clearer next step.','A reasoned comparison. The final choice is always yours.')+`<section class="verdict"><span class="pill">${({hold:'HOLD',consider:'CONSIDER',skip:'SKIP',needs_more_info:'NEED MORE INFO'})[result.decision]}</span><h2>${labels[result.decision]}</h2><p class="muted">${esc(candidate().name)} · ${result.confidence} confidence · ${result.scan_used?'YouCam observations available; verdict based on routine data':'No skin scan used'}</p></section>${readerControls()}<div class="split"><section><h2>What this is based on</h2>${result.reasons.map((r,i)=>`<article class="evidence"><div class="eyebrow">0${i+1} · ROUTINE CONTEXT</div><p>${esc(r.text)}</p><small>Source: ${esc(r.source)}</small></article>`).join('')}</section><aside class="panel"><h2>What we don’t know</h2><ul class="reason-list">${result.unknowns.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><h3>Your next steps</h3><ul class="reason-list">${result.next.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></aside></div><div class="button-row"><button class="primary" id="save">Save text summary <span>↓</span></button><button class="secondary" id="download">Download summary</button><button class="secondary" data-go="check">Edit comparison</button></div><p class="muted" style="margin-top:20px;font-size:10px">This is educational shopping support, not a safety assessment or a medical diagnosis. A scan is never proof that you need a product.</p>`;}
function scan(){return heading('SKIN INSIGHTS · OPTIONAL','Another layer of understanding.','A photo can add visible skin observations. You can always continue without one.')+`<div class="split"><section class="panel"><h2>A moment for your skin.</h2><p class="muted">Use even natural light, face the camera, and remove glasses. Upload a clear photo with one face, at least 480 pixels on each side.</p><div class="notice">Live analysis requires a configured YouCam connection. We’ll check availability before uploading your photo. No simulated results are used.</div><label class="check-row"><input type="checkbox" id="consent">I am 18 or older and consent to sending this photo to YouCam for cosmetic skin analysis. I understand that it is not a medical assessment.</label><div class="scan-drop"><label class="form-field">Choose your photo (JPEG or PNG, up to 10 MB)<input type="file" id="photo" accept="image/jpeg,image/png"></label><img id="photo-preview" alt="Your selected photo preview" ${photoUrl?`src="${photoUrl}"`:'hidden'}></div><button class="primary" id="analyze">Analyze with YouCam <span>↗</span></button><button class="link-btn" data-go="check" style="margin-left:15px">Continue without a scan →</button><div id="scan-status" class="status" role="status" aria-live="polite"></div>${state.scan?`<section class="selected-info" style="margin-top:20px"><h3>Live YouCam observations</h3><small>${esc(state.scan.timestamp)}</small>${state.scan.fields.map(f=>`<p>${esc(f.name)}: ${esc(f.score)}</p>`).join('')}<p>Cosmetic observations only. Lighting and image quality affect results. Scores do not indicate product need.</p></section>`:''}</section><aside class="panel" style="align-self:start"><span class="scan-icon">♧</span><h2>Your photo, your choice.</h2><p class="muted">Your photo preview stays in this tab until you choose to analyze. This app does not save original photos or scan results to persistent storage.</p><p class="muted">When enabled, YouCam processes your image under its own terms. When connected, Supabase holds task references for 15 minutes, then scheduled cleanup removes expired records. Photos and observation scores are not saved there. Provider retention is separate.</p><a class="link-btn" href="https://www.perfectcorp.com/business/info/privacy" target="_blank" rel="noopener">Read provider privacy information ↗</a><p class="muted" style="margin-top:20px">Saved summaries contain text only. Delete this session to remove this guest’s app-held data and saved summaries, including any saved in Supabase.</p></aside></div>`;}
function saved(){return heading('A RECORD OF THOUGHTFUL CHOICES','Your saved decisions.',backend.configured?'Text-only summaries, saved privately to your guest session when you choose to save them.':'Text-only summaries, saved on this browser when you choose to save them.')+(savedLoading?'<p class="status" role="status">Loading your saved decisions…</p>':savedError?`<div class="notice" role="alert">${esc(savedError)} <button class="secondary" id="retry-saved">Retry</button></div>`:state.saved.length?state.saved.map((s,i)=>`<article class="saved-card"><div class="eyebrow">${esc(s.date)} · ${esc(s.decision.replaceAll('_',' '))}</div><h3>${esc(s.name)}</h3><p>${esc(s.summary)}</p><button class="secondary" data-remove-save="${i}">Remove summary ×</button></article>`).join(''):`<section class="empty"><span style="font-size:36px">♧</span><h2>A little space for clarity.</h2><p class="muted">Your saved comparisons will live here. No photos, just your next steps.</p><button class="primary" data-go="check">Check your first product ↗</button></section>`);}
function render(){main.innerHTML=({home,shelf,check,decision,scan,saved})[page]();bind();}
function bind(){bindReader();document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>toggle(b.dataset.add));document.querySelectorAll('[data-remove-save]').forEach(b=>b.onclick=()=>removeSaved(+b.dataset.removeSave,b));if($('#retry-saved'))$('#retry-saved').onclick=loadSaved;if($('#search'))$('#search').oninput=e=>{query=e.target.value;refreshCatalog();};if($('#category'))$('#category').onchange=e=>{category=e.target.value;refreshCatalog();};if($('#candidate'))$('#candidate').onchange=e=>{state.candidate=e.target.value;$('#candidate-info').innerHTML=candidateInfo();};if($('#compare-form'))$('#compare-form').onsubmit=e=>{e.preventDefault();state.budget=$('#budget').value;state.goal=$('#goal').value;state.sensitive=$('#sensitive').checked;result=compare(current(),candidate(),{budget:Number(state.budget),goal:state.goal,sensitive:state.sensitive,scanUsed:!!state.scan});go('decision');};if($('#how'))$('#how').onclick=()=>modal('<div class="eyebrow">THREE SMALL STEPS</div><h2>Get to know your shelf.</h2><ol><li>Add the products you already use from our fictional sample collection.</li><li>Choose one product you’re considering and tell us your goal.</li><li>See a transparent decision, with reasons, unknowns and next steps.</li></ol><p>A skin scan is optional. This prototype uses illustrative product data; it cannot predict suitability or product effectiveness.</p><button class="primary" id="modal-start">Build my shelf ↗</button>');if($('#tip'))$('#tip').onclick=()=>modal('<h2>Make room for intention.</h2><p>A similar role or shared ingredient can be a reason to pause and compare full formulations. It doesn’t establish that products are equivalent.</p><p>Start with what you already use, your actual experience, and the goal you care about.</p>');if($('#save'))$('#save').onclick=save;if($('#download'))$('#download').onclick=download;if($('#photo'))$('#photo').onchange=photoChange;if($('#analyze'))$('#analyze').onclick=analyze;}
function refreshCatalog(){$('#catalog').innerHTML=catalogGrid('add');document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>toggle(b.dataset.add));}
function toggle(id){if(state.routine.includes(id))state.routine=state.routine.filter(x=>x!==id);else{if(state.routine.length>=6)return toast('Keep your sample shelf to 6 products.');state.routine.push(id);}const q=query,c=category;render();query=q;category=c;if($('#search')){$('#search').value=q;$('#category').value=c;refreshCatalog();}counters();}
function persist(){try{localStorage.setItem('shelfcheck-saved',JSON.stringify(state.saved));}catch{toast('Browser storage unavailable. Download your summary instead.');}}
function summary(){return `ShelfCheck — ${candidate().name}\n${labels[result.decision]}\n\n${result.reasons.map(r=>r.text+'\nSource: '+r.source).join('\n\n')}\n\nUnknowns: ${result.unknowns.join(' ')}\n\nNext steps: ${result.next.join(' ')}\n\n${result.scan_used?'YouCam observations were available; verdict uses routine data.':'No skin scan used.'}\nFictional sample products. Educational guidance, not medical advice.\n${new Date().toISOString()}`;}
async function save(){
 if(savePending)return;
 const item={name:candidate().name,decision:result.decision,summary:summary(),date:new Date().toLocaleDateString()};
 const version=sessionVersion;savePending=true;const button=$('#save');if(button)button.disabled=true;
 try{
  const savedItem=backend.configured?await mutate(()=>backend.saveSaved(item)):item;
  if(version!==sessionVersion)return;
  state.saved.unshift(savedItem);if(!backend.configured)persist();counters();
  toast(backend.configured?'Text summary saved to your private guest session.':'Text summary saved on this browser.');
 }catch(e){toast(e.message);}finally{savePending=false;if(document.contains(button))button.disabled=false;}
}
async function removeSaved(index,button){
 const item=state.saved[index];if(!item)return;const version=sessionVersion;button.disabled=true;
 try{if(backend.configured)await mutate(()=>backend.removeSaved(item.id));if(version!==sessionVersion)return;state.saved=state.saved.filter(s=>s!==item);if(!backend.configured)persist();render();counters();}
 catch(e){toast(e.message);if(document.contains(button))button.disabled=false;}
}
async function loadSaved(){
 if(!backend.configured)return;
 const version=sessionVersion;savedLoading=true;savedError='';if(page==='saved')render();
 try{const items=await mutate(()=>backend.listSaved());if(version!==sessionVersion)return;state.saved=items;$('#backend-status').textContent='Private guest session · Text summaries save to Supabase when you choose Save.';}
 catch(e){if(version!==sessionVersion)return;savedError=e.message;$('#backend-status').textContent='Cloud connection unavailable. Comparisons and downloads still work.';}
 finally{if(version===sessionVersion){savedLoading=false;counters();if(page==='saved')render();}}
}

function download(){const url=URL.createObjectURL(new Blob([summary()],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download='shelfcheck-summary.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function photoChange(e){file=null;if(photoUrl)URL.revokeObjectURL(photoUrl);photoUrl=null;const p=$('#photo-preview');p.hidden=true;const f=e.target.files[0];if(!f)return;if(!['image/jpeg','image/png'].includes(f.type)||f.size>10*1024*1024){e.target.value='';return $('#scan-status').textContent='Choose a JPEG or PNG smaller than 10 MB.';}try{const img=await createImageBitmap(f);if(img.width<480||img.height<480||Math.max(img.width,img.height)>4096){img.close();e.target.value='';return $('#scan-status').textContent='Use a photo at least 480 pixels on each side and no more than 4096 pixels on the longest side.';}img.close();file=f;photoUrl=URL.createObjectURL(f);p.src=photoUrl;p.hidden=false;$('#scan-status').textContent='Photo ready. It has not been uploaded.';}catch{$('#scan-status').textContent='This image could not be read. Please try another JPEG or PNG.';}}
async function analyze(){const status=$('#scan-status');if(!$('#consent').checked)return status.textContent='Please give explicit consent before sending a photo, or continue without scanning.';if(!file)return status.textContent='Choose a supported photo first.';const button=$('#analyze');button.disabled=true;scanController=new AbortController();try{if(!backend.configured)throw Error('Supabase is not connected yet. Your photo has not been uploaded. Continue without a scan.');const c=await backend.scanConfig(scanController.signal);if(!c.youcamConfigured)throw Error('YouCam is not connected in this deployment. Your photo has not been uploaded. Continue with a routine-only comparison.');status.textContent='Sending your consented photo to YouCam…';const form=new FormData();form.append('photo',file);form.append('consent','true');const data=await backend.startScan(form,scanController.signal);status.textContent='YouCam is processing your photo. You may continue without a scan.';for(let i=0;i<30;i++){await new Promise(r=>setTimeout(r,10000));if(scanController.signal.aborted)throw Error('Session deleted.');const d=await backend.pollScan(data.id,scanController.signal);if(d.status==='success'){state.scan=d;go('scan');return;}if(d.status==='error')throw Error(d.error||'YouCam could not analyze the photo. Try even lighting and one visible face.');}throw Error('Analysis timed out. Please try again or continue without a scan.');}catch(e){if(e.name!=='AbortError'&&document.contains(status))status.textContent=e.message;}finally{if(document.contains(button))button.disabled=false;}}
let voiceId='',readingRate='1';
const reader=createReader({synth:window.speechSynthesis,Utterance:window.SpeechSynthesisUtterance,onState:updateReader});
function readerControls(){return `<section class="reader-panel" aria-labelledby="reader-title"><div class="reader-heading"><div><div class="eyebrow">YOUR DECISION, OUT LOUD</div><h2 id="reader-title">Prefer to listen?</h2><p>Hear the verdict, reasons, uncertainties and next steps.</p></div><button class="primary" id="read-aloud" ${reader.supported?'':'disabled'}>Read aloud <span aria-hidden="true">▷</span></button></div><div class="reader-options"><label>Voice<select id="reader-voice" ${reader.supported?'':'disabled'}><option value="">Device default (English)</option></select></label><label>Speed<select id="reader-rate" ${reader.supported?'':'disabled'}>${[['0.8','Slower · 0.8×'],['1','Normal · 1×'],['1.2','Faster · 1.2×']].map(([v,t])=>`<option value="${v}" ${readingRate===v?'selected':''}>${t}</option>`).join('')}</select></label><div class="reader-actions"><button class="secondary" id="reader-pause" disabled>Pause</button><button class="secondary" id="reader-stop" disabled>Stop</button></div></div><p id="reader-status" role="status" aria-live="polite">${reader.supported?'Ready when you are. Audio starts only when you choose Read aloud.':'Read aloud is unavailable in this browser. You can still read all the text below.'}</p><small>Voices are provided by your device or browser; some may require internet. No microphone is used.</small></section>`;}
function updateReader({status,message}){const read=$('#read-aloud'),pause=$('#reader-pause'),stop=$('#reader-stop');if(!read)return;const busy=['starting','speaking','paused'].includes(status);read.disabled=!reader.supported||busy;read.innerHTML='Read aloud <span aria-hidden="true">▷</span>';pause.disabled=!busy;pause.textContent=status==='paused'?'Resume':'Pause';stop.disabled=!busy;$('#reader-status').textContent=message;}
function refreshVoices(){const select=$('#reader-voice');if(!select)return;const voices=window.speechSynthesis?.getVoices().filter(v=>/^en(?:-|$)/i.test(v.lang))||[];select.innerHTML='<option value="">Device default (English)</option>'+voices.map(v=>`<option value="${esc(v.voiceURI)}">${esc(v.name)} · ${esc(v.lang)}${v.localService?' · device voice':''}</option>`).join('');select.value=voiceId;if(select.selectedIndex<0){select.value='';voiceId='';}}
function bindReader(){if(!$('#read-aloud'))return;refreshVoices();$('#read-aloud').onclick=()=>reader.start(decisionNarration(candidate(),result),{rate:Number(readingRate),voice:window.speechSynthesis?.getVoices().find(v=>v.voiceURI===voiceId)});$('#reader-pause').onclick=()=>reader.status==='paused'?reader.resume():reader.pause();$('#reader-stop').onclick=()=>reader.stop();$('#reader-rate').onchange=e=>{readingRate=e.target.value;reader.stop('Speed updated. Select Read aloud to restart.');};$('#reader-voice').onchange=e=>{voiceId=e.target.value;reader.stop('Voice updated. Select Read aloud to restart.');};}
window.speechSynthesis?.addEventListener('voiceschanged',refreshVoices);
window.addEventListener('pagehide',()=>reader.stop());
document.addEventListener('visibilitychange',()=>{if(document.hidden)reader.stop('Reading stopped while this tab is hidden.');});
document.querySelectorAll('.nav').forEach(b=>b.onclick=()=>go(b.dataset.page));$('.brand').onclick=e=>{e.preventDefault();go('home');};$('#modal .close').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target.id==='modal-start'){$('#modal').close();go('shelf');}});$('#privacy').onclick=()=>modal('<div class="eyebrow">PRIVACY, IN PLAIN LANGUAGE</div><h2>Your space. Your choice.</h2><p>Your routine and photo preview live in this tab. Closing or reloading clears them. Photos are sent to YouCam only after explicit consent and an analysis request.</p><p>When connected, Supabase stores short-lived task references, not photos or scores. Tasks become inaccessible after 15 minutes and scheduled cleanup removes expired references. YouCam has separate data practices; deleting this session does not guarantee provider deletion.</p><p>When Supabase is connected, summaries you explicitly save are stored privately in its database. A guest session token stays in this browser; clearing browser data loses access. In local preview mode, summaries stay on this device. No photo is saved. Delete this session removes your app-held summaries and guest account.</p><p>This prototype provides cosmetic shopping education, not medical advice. All catalogue items and prices are fictional examples.</p>');$('#delete').onclick=()=>modal('<h2>Delete this session?</h2><p>This deletes your saved summaries and guest account from Supabase when connected, and clears this device’s shelf and photo preview. Provider-held data is governed separately by YouCam. This cannot be undone.</p><button class="primary" id="confirm-delete">Delete session</button>');$('#modal').addEventListener('click',async e=>{if(e.target.id!=='confirm-delete')return;reader.stop();scanController?.abort();const button=e.target;button.disabled=true;try{if(backend.configured)await mutate(()=>backend.deleteSession());}catch(error){button.disabled=false;return toast(error.message);}sessionVersion++;savedError='';savedLoading=false;state.routine=[];state.saved=[];state.scan=null;state.candidate='sample_5';state.goal='Hydration';state.budget='';state.sensitive=false;result=null;file=null;if(photoUrl)URL.revokeObjectURL(photoUrl);photoUrl=null;try{localStorage.removeItem('shelfcheck-saved');}catch{}$('#modal').close();go('home');$('#backend-status').textContent=backend.configured?'Session deleted. A new private guest session starts when you save or scan.':'Local preview · Saved decisions stay in this browser.';toast('Your app-held session data has been cleared.');});go('home',false);

$('#mobile-privacy').onclick=()=>$('#privacy').click();$('#mobile-delete').onclick=()=>$('#delete').click();

$('#backend-status').textContent=backend.configured?'Connecting to your private guest session…':'Local preview · Cloud saving is not connected yet.';
if(backend.configured)loadSaved();
